head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL00006";

// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.usrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00006.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb1", attr: "label", fn: function () { return String(dma_disclosureVo.get("tgtIsurCd")); } },
        { childId: "__rb2", attr: "label", fn: function () { return String(dma_disclosureVo.get("tgtFssUnqNo")); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_disclosureVo.get("tgtComNm")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_usrTpCd", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("mainFormNm") ?? ""))) + "(자회사의 주요경영사항)"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.progress_bar(true);
        (document.htmlTransFrm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureHTML';
        requestAsyncXMLHTTP(htmlTransFrm, "post");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00006.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 3건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["corpUsrTpCd","listStatCd","bndDisclsCorpStatCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00006' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_41_onclick
 * @description img_41 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_41_onclick = function(e){
    try {
        fn_ViewManualKeyWord(0200000017)  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_ViewManualKeyWord — as-is 정의 없음(원본 JS 미제공 — 회신)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00006.img_41_onclick' }); }
};

/**
 * @method
 * @name img_70_onclick
 * @description img_70 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_70_onclick = async function(e){
    try {
        await scwin.goPrint()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00006.img_70_onclick' }); }
};

/**
 * @method
 * @name img_71_onclick
 * @description img_71 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_71_onclick = async function(e){
    try {
        await scwin.submit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00006.img_71_onclick' }); }
};

/**
 * @method
 * @name img_72_onclick
 * @description img_72 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_72_onclick = function(e){
    try {
        scwin.goList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00006.img_72_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_submit
 * @description submit 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_submit = async function (action) {
    const sbmOptions = {
        id: "tx_fn_submit",
        method: "post",
        action: action ?? "/submission/submit.do?method=searchSubmitInformationForm",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_goPrint
 * @description go Print 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goPrint = async function (action) {
    try { return await $c.data.downFile(action ?? "/submission/disclosure.do?method=searchDisclosureContentPrint", "", ($c.util.getComponent("dma_goPrintReq") ? $c.util.getComponent("dma_goPrintReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function () {
    const corpUsrTpCd = $c.util.getComponent('dma_submitReq').get('corpUsrTpCd');
    const listStatCd = $c.util.getComponent('dma_submitReq').get('listStatCd');
    const bndDisclsCorpStatCd = $c.util.getComponent('dma_submitReq').get('bndDisclsCorpStatCd');
    if (corpUsrTpCd === '11' || corpUsrTpCd === '21' || corpUsrTpCd === '61') {
        if ((corpUsrTpCd === '11' && (String(((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })())) == null ? '' : ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })())) == null ? '' : ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })())))) === '1') || (corpUsrTpCd === '21' && (String(((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })())) == null ? '' : ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })())) == null ? '' : ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })())))) === '2') || (corpUsrTpCd === '61' && (String(((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })())) == null ? '' : ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })())) == null ? '' : ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })())))) === '6')) {
            if (listStatCd === 'Y') {
                await scwin.tx_fn_submit('submit.do?method=searchSubmitInformationForm');
            } else {
                await $c.win.alert("상장폐지법인은 공시를 제출할 수 없습니다.");
                return;
            }
        } else {
            await $c.win.alert("상장폐지법인은 공시를 제출할 수 없습니다.");
            return;
        }
    } else {
        if (corpUsrTpCd === '19') {
            if (bndDisclsCorpStatCd === '1') {
                await scwin.tx_fn_submit('submit.do?method=searchSubmitInformationForm');
            } else {
                await $c.win.alert("상장폐지법인은 공시를 제출할 수 없습니다.");
                return;
            }
        } else {
            await scwin.tx_fn_submit('submit.do?method=searchSubmitInformationForm');
        }
    }
};

/**
 * @method
 * @name goBack
 * @description go Back 처리
 * @returns {void}
 * @hidden N
 */
scwin.goBack = function () {
    history.go(-1);
};

/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {void}
 * @hidden N
 */
scwin.goList = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/JLDFIL00500.xml');
};

/**
 * @method
 * @name goPrint
 * @description go Print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goPrint = async function () {
    let action;
    (document.printFrm || { elements: [] }).target = 'printWin';
    action = 'disclosure.do?method=searchDisclosureContentPrint';
    (Promise.resolve($c.win.openPopup("/ui/jsp/PROGRESS_BLANK_POP.xml", { id: "printWin", scrollbars: true, resizable: true, width: "835", height: "550", type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("printWin"); this.closed = true; } });  // TODO Stage2(V48): 대상 화면 PROGRESS_BLANK_POP 이(가) ui-tobe 에 없음(미전환·공통 팝업) — 경로 확인
    await scwin.tx_fn_goPrint(action);
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} transHtmlDoc transHtmlDoc
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (transHtmlDoc) {
    scwin.progress_bar(false);
    ($c.util.getComponent('txt_htmlContent') && $c.util.getComponent('txt_htmlContent').setValue) ? $c.util.getComponent('txt_htmlContent').setValue(transHtmlDoc) : (($c.util.getComponent('txt_htmlContent') && $c.util.getComponent('txt_htmlContent').setText) ? $c.util.getComponent('txt_htmlContent').setText(transHtmlDoc) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'txt_htmlContent'), void (transHtmlDoc)));
};

/**
 * @method
 * @name progress_bar
 * @description progress bar 처리
 * @param {*} display display
 * @returns {void}
 * @hidden N
 */
scwin.progress_bar = function (display) {
    const on = (display === undefined || display === 'block' || display === true);
    const cu = $c.util.getComponent('progress_bar_curtain');
    const pb = $c.util.getComponent('prg_processing');
    if (on) {
        if (cu && cu.show) {
            cu.setStyle("display", "");
        }
        if (pb && pb.show) {
            pb.setStyle("display", "");
        }
    } else {
        if (cu && cu.hide) {
            cu.setStyle("display", "none");
        }
        if (pb && pb.hide) {
            pb.setStyle("display", "none");
        }
    }
};
